-- Tabel untuk materials
DROP TABLE IF EXISTS "materials";
CREATE TABLE IF NOT EXISTS "materials" (
  "id" TEXT,
  "urutan_subbab" TEXT,
  "mapel" TEXT,
  "pdf_filename" TEXT,
  "jenjang" TEXT,
  "bab" TEXT,
  "urutan_bab" TEXT,
  "pdf_path" TEXT,
  "updated_at" TEXT,
  "kelas" TEXT,
  "tipe" TEXT,
  "rangkuman_gambar_url" TEXT,
  "created_at" TEXT,
  "judul" TEXT,
  "pdf_url" TEXT,
  "ringkasan" TEXT,
  "rangkuman_gambar_path" TEXT,
  "isi" TEXT
);

